// High-level handler that coordinates the communication cycle
void handle_requests() {
    switch (rank) {
        case 1: {
            send_outputs_from_rank_1();
            receive_inputs_for_rank_1();
            top->eval();
            break;
        }
        case 2: {
            send_outputs_from_rank_2();
            receive_inputs_for_rank_2();
            top->eval();
            break;
        }
        case 3: {
            send_outputs_from_rank_3();
            receive_inputs_for_rank_3();
            top->eval();
            break;
        }
        case 4: {
            send_outputs_from_rank_4();
            receive_inputs_for_rank_4();
            top->eval();
            break;
        }
        default: break;
    }
}

int main(int argc, char** argv) {
    mpi_initialize();

    top = new Vtile;

    rank = getRank();
    size = getSize();

    std::cout << "Partition 'tile' is alive on Rank " << rank << " of " << size << std::endl;

    switch (rank) {
        case 1: initialize_partition_tile0(); break;
        case 2: initialize_partition_tile1(); break;
        case 3: initialize_partition_tile2(); break;
        case 4: initialize_partition_tile3(); break;
        default: break;
    }

    top->eval();
    MPI_Barrier(MPI_COMM_WORLD);

    bool sim_end = false;
    while (!sim_end) {
        if (rank != 0) {
             handle_requests();
        }

        int shutdown_flag = 0;
        MPI_Status status;
        MPI_Iprobe(0, SHUTDOWN_TAG, MPI_COMM_WORLD, &shutdown_flag, &status);
        if (shutdown_flag) {
            int dummy;
            MPI_Recv(&dummy, 1, MPI_INT, 0, SHUTDOWN_TAG, MPI_COMM_WORLD, &status);
            sim_end = true;
        }
    }

    std::cout << "Rank " << rank << ": Shutting down." << std::endl;

    cleanup(0);
    return 0;
}
